// HMAC-SHA256 (RFC 2104) built on the pure-JS SHA-256 in sha256.mjs.

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(key, message) {
  let k = key;
  if (k.length > BLOCK_SIZE) {
    k = sha256(k);
  }
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(k);

  const ipad = new Uint8Array(BLOCK_SIZE + message.length);
  const opad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    ipad[i] = paddedKey[i] ^ 0x36;
    opad[i] = paddedKey[i] ^ 0x5c;
  }
  ipad.set(message, BLOCK_SIZE);

  const inner = sha256(ipad);
  const outer = new Uint8Array(BLOCK_SIZE + inner.length);
  outer.set(opad);
  outer.set(inner, BLOCK_SIZE);
  return sha256(outer);
}

