      if (eq !== -1) {
        optName = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
    }

    const spec = OPTION_SPECS.find((s) => s.name === optName);
    if (!spec) {
      extras.push(token);
      continue;
    }

    let value;
    if (inlineValue !== null) {
      value = inlineValue;
    } else {
      if (i + 1 >= argv.length || looksLikeOption(argv[i + 1])) {
        fail(prog, `argument ${spec.name}: expected one argument`);
      }
      value = argv[++i];
    }

    if (spec.choices && !spec.choices.includes(value)) {
      const choiceList = spec.choices.map((c) => `'${c}'`).join(', ');
      fail(prog, `argument ${spec.name}: invalid choice: '${value}' (choose from ${choiceList})`);
    }

    values[spec.name] = value;
  }

  const missing = OPTION_SPECS.filter((s) => s.required && !(s.name in values)).map((s) => s.name);
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    data: values['--data'],
    verify_iat: values['--verify_iat'],
  };
}

